begin;
set local statement_timeout='30s';
do $$
declare a uuid:=gen_random_uuid(); u uuid:=gen_random_uuid(); v uuid:=gen_random_uuid(); sid uuid:=gen_random_uuid(); sid2 uuid:=gen_random_uuid(); oid uuid:=gen_random_uuid(); driver uuid:=gen_random_uuid(); appid uuid:=gen_random_uuid(); fid uuid:=gen_random_uuid(); fid2 uuid:=gen_random_uuid(); r jsonb; denied boolean; email text; ve text; aid uuid;
begin
 email:=u::text||'@handling-test.invalid';ve:=v::text||'@handling-test.invalid';
 insert into auth.users(id,email,email_confirmed_at) values(a,a::text||'@handling-test.invalid',now()),(u,email,now()),(v,ve,now());
 insert into public.platform_admins(user_id) values(a);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);
 insert into public.stores(id,name,category,owner_email,pickup_enabled) values(sid,'Temporary owned shop','shop',email,true),(sid2,'Other shop','shop',ve,true);
 insert into public.business_applications(id,owner_id,store_id,status) values(appid,u,sid,'approved');
 insert into public.store_drivers(id,store_id,user_id,name,phone,email) values(driver,sid,u,'Temporary courier','+963900000001',email);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated')::text,true);
 insert into public.orders(id,store_id,customer_id,customer_name,phone,address,area,delivery_fee,items,subtotal,total,status,driver_id) values(oid,sid,u,'Fixture','+963900000001','Fixture','Fixture',0,'[]',12,12,'جديد',driver);
 denied:=false;begin perform public.admin_account_deletion_details(u);exception when others then denied:=SQLERRM='ADMIN_REQUIRED';end;
 if not denied then raise exception 'Non-admin details allowed';end if;
 denied:=false;begin perform public.admin_handle_account_deletion(u,'transfer_shop',sid,ve,'HANDLE '||email,true);exception when others then denied:=SQLERRM='ADMIN_REQUIRED';end;
 if not denied then raise exception 'Non-admin action allowed';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);
 r:=public.admin_account_deletion_details(u);
 if jsonb_array_length(r->'orders')<>1 or jsonb_array_length(r->'drivers')<>1 or jsonb_array_length(r->'applications')<>1 then raise exception 'Handling manifest incomplete';end if;
 denied:=false;begin perform public.admin_handle_account_deletion(u,'transfer_shop',sid,ve,'HANDLE wrong',true);exception when others then denied:=SQLERRM='CONFIRMATION_REQUIRED';end;
 if not denied then raise exception 'Wrong identity allowed';end if;
 denied:=false;begin perform public.admin_handle_account_deletion(u,'transfer_shop',sid,ve,'HANDLE '||email,false);exception when others then denied:=SQLERRM='VERIFICATION_REQUIRED';end;
 if not denied then raise exception 'Unverified action allowed';end if;
 denied:=false;begin perform public.admin_handle_account_deletion(a,'transfer_shop',sid,ve,'HANDLE '||a::text||'@handling-test.invalid',true);exception when others then denied:=SQLERRM='PROTECTED_ACCOUNT';end;
 if not denied then raise exception 'Protected action allowed';end if;
 denied:=false;begin perform public.admin_handle_account_deletion(u,'transfer_shop',sid,email,'HANDLE '||email,true);exception when others then denied:=SQLERRM='DESTINATION_NOT_FOUND';end;
 if not denied then raise exception 'Same owner allowed';end if;
 denied:=false;begin perform public.admin_handle_account_deletion(u,'transfer_shop',sid2,ve,'HANDLE '||email,true);exception when others then denied:=SQLERRM='RESOURCE_CHANGED';end;
 if not denied then raise exception 'Other user shop changed';end if;
 denied:=false;begin perform public.admin_handle_account_deletion(u,'detach_application',appid,null,'HANDLE '||email,true);exception when others then denied:=SQLERRM='TRANSFER_SHOP_FIRST';end;
 if not denied then raise exception 'Application detached before shop';end if;
 denied:=false;begin perform public.admin_handle_account_deletion(u,'detach_driver',driver,null,'HANDLE '||email,true);exception when others then denied:=SQLERRM='DRIVER_ORDERS_OPEN';end;
 if not denied then raise exception 'Working courier detached';end if;
 r:=public.admin_handle_account_deletion(u,'cancel_order',oid,null,'HANDLE '||email,true);
 if r->>'handled'<>'true' or not exists(select 1 from public.orders where id=oid and status='ملغي' and total=12) then raise exception 'Order cancellation failed';end if;
 r:=public.admin_handle_account_deletion(u,'detach_driver',driver,null,'HANDLE '||email,true);
 if not exists(select 1 from public.store_drivers d where d.id=driver and d.user_id is null and d.phone='' and not d.active and d.deleted_at is not null and d.email like '%@deleted.damascus-shop.invalid') then raise exception 'Courier unlink failed';end if;
 r:=public.admin_handle_account_deletion(u,'transfer_shop',sid,ve,'HANDLE '||email,true);
 if not exists(select 1 from public.stores where id=sid and owner_email=ve) or not exists(select 1 from public.business_applications where id=appid and store_id is null and owner_id=u) then raise exception 'Shop transfer failed';end if;
 -- Standalone approved application can be unlinked without exposing its personal data to the new owner.
 update public.business_applications set store_id=sid,status='approved' where id=appid;
 r:=public.admin_handle_account_deletion(u,'detach_application',appid,null,'HANDLE '||email,true);
 if not exists(select 1 from public.business_applications where id=appid and store_id is null) then raise exception 'Application unlink failed';end if;
 insert into storage.buckets(id,name) values(u::text,u::text);
 insert into storage.objects(id,bucket_id,name,owner,owner_id) values(fid,u::text,'private-unused.webp',u,u::text),(fid2,u::text,'kept-shop.webp',u,u::text);
 update public.stores set image='https://example.invalid/kept-shop.webp' where id=sid;
 r:=public.admin_account_deletion_file(u,fid,'HANDLE '||email,true);
 if r->>'name'<>'private-unused.webp' or r->>'bucket'<>u::text then raise exception 'File manifest wrong';end if;
 denied:=false;begin perform public.admin_account_deletion_file(u,fid2,'HANDLE '||email,true);exception when others then denied:=SQLERRM='FILE_IN_USE';end;
 if not denied then raise exception 'In-use file deletion allowed';end if;
 r:=public.admin_handle_account_deletion(u,'transfer_file',fid2,ve,'HANDLE '||email,true);
 if not exists(select 1 from storage.objects where id=fid2 and owner_id=v::text and owner=v) then raise exception 'File ownership not transferred';end if;
 denied:=false;begin perform public.admin_account_deletion_file(u,fid2,'HANDLE '||email,true);exception when others then denied:=SQLERRM='RESOURCE_CHANGED';end;
 if not denied then raise exception 'Other owner file allowed';end if;
 r:=public.admin_handle_account_deletion(u,'transfer_file',fid,ve,'HANDLE '||email,true);
 r:=public.admin_execute_account_deletion(u,'DELETE '||email,true,null);
 if r->>'deleted'<>'true' or exists(select 1 from auth.users where id=u) then raise exception 'Account still blocked after handling';end if;
 if (select count(*) from public.account_deletion_actions where target_id=u)<>6 then raise exception 'Action audit missing';end if;
 if has_function_privilege('anon','public.admin_handle_account_deletion(uuid,text,uuid,text,text,boolean)','EXECUTE') then raise exception 'Anon execute granted';end if;
end; $$;
rollback;
select 'PASS: admin guards, confirmations, protected accounts, scoped resources, shop/application transfer, order cancellation, courier unlink, in-use file protection, file ownership, final deletion and audit. All fixtures rolled back.' result;
